// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep the admissible domain wide but avoid trivial zero-deposit/zero-withdraw cases.
        depositAmount = bound(depositAmount, c.MinDeposit(), 1e30);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(actor);

        vm.prank(actor);
        c.CashOut(withdrawAmount);

        uint256 balanceAfter = c.balances(actor);

        // General rule: after a successful CashOut, the caller's balance must equal
        // the pre-call balance minus the withdrawn amount. The mutant adds the amount
        // instead, so it satisfies balanceAfter == balanceBefore + withdrawAmount,
        // which is strictly larger and violates this invariant.
        assertTrue(balanceAfter == balanceBefore - withdrawAmount);
    }
}
